    var dsNm = 'BNS_INST_INFO';
    var qryId = 'lds.stf.bnscommon.select.listInstCd';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_InstCd, dsNm, qryId, "&{P}V_INST_NM=");

    //공통콤보
    var arrCid = [];
    arrCid.push({
        cid: '02475',
        cnm: 'cmb_CurrTpCd'
