    }); //유동화					
    arrCid.push({
        cid: '03054',
        cnm: 'cmb_ImbdoptCorpbndCd'
    }); //옵션					
    arrCid.push({
        cid: '03563',
        cnm: 'cmb_CondCapSecuTpCd'
    }); //조건부자본증권유형		
    arrCid.push({
        cid: '03053',
        cnm: 'cmb_DebtRepayRankTpCd'
