    }); //이자원단위 미만처리		
    arrCid.push({
        cid: '03114',
        cnm: 'cmb_BndOddllotddIntBasTpCd'
    }); //단수일 이자기준			
    arrCid.push({
        cid: '01510',
        cnm: 'cmb_BndSaleTpCd'
    }); //매출형태				
    arrCid.push({
        cid: '02253',
        cnm: 'cmb_IntMmendTpCd'
    }); //이자월말구분			
    arrCid.push({
        cid: '01562',
