 * 설명       : 신용평가기관을 설정한다.
 ***********************************************/
scwin.fn_SetCreditCombo = function(obj, cd, val) {
    var cbdata = "^ ," + cd + "^" + val;
    obj.CBData = cbdata;
    $c.stf.setObjectValue(obj, cd);
};


/********************************************** 
 * 함수명   : fn_GetParApprovFileWrt
 * 설명       : 결재파일작성 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParApprovFileWrt = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: scwin.vBndApplId,
        BND_LIST_PROCS_TP_CD: scwin.vBndListProcsTpCd,
        BND_MKTACT_TP_CD: dts_List.getCellData(dts_List.getRowPosition(), 'BND_MKTACT_TP_CD')
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_GetParBndBasNm
