/********************************************** 
 * 함수명   : fn_SetUdwrtInst
 * 설명       : 인수기관 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetUdwrtInst = function(rowIdx, cbObj, edtObj) {
    var UDWRT_INST_CD = dts_UdwrtInst.getCellData(rowIdx, 'UDWRT_INST_CD');
    if (UDWRT_INST_CD == '9999') {
        $c.stf.setObjectValue(edt_UdwrtAmt5, dts_UdwrtInst.getCellData(rowIdx, 'UDWRT_AMT'));
    } else {
        $c.stf.setObjectValue(cbObj, dts_UdwrtInst.getCellData(rowIdx, 'UDWRT_INST_CD'));
        $c.stf.setObjectValue(edtObj, dts_UdwrtInst.getCellData(rowIdx, 'UDWRT_AMT'));
    }
};



/********************************************** 
 * 함수명   : fn_SetBtn
 * 설명       : 버튼보이기를 설정한다.
 ***********************************************/
scwin.fn_SetBtn = function() {
    if (scwin.vBndListProcsTpCd == 3) {
        $c.stf.showObj(btn_StdCdReq, false);
        return;
    }
    if ($c.stf.getObjectValue(txb_StdCd) == '') {
        $c.stf.showObj(btn_StdCdReq, true);
        btn_ProcsComplt.src = '../img/bns/btn_20_d.gif';
        btn_ProcsComplt.setDisabled(true);
        btn_TeamleadrConfrm.src = '../img/bns/btn_21_d.gif';
        btn_TeamleadrConfrm.setDisabled(true);
    } else {
        $c.stf.showObj(btn_StdCdReq, false);
        if (scwin.vProcsStatCd == "2") {
            btn_ProcsComplt.src = '../img/bns/btn_20_d.gif';
            btn_ProcsComplt.setDisabled(true);
            btn_TeamleadrConfrm.src = '../img/bns/btn_21.gif';
            btn_TeamleadrConfrm.setDisabled(false);
        } else {
            btn_ProcsComplt.src = '../img/bns/btn_20.gif';
            btn_ProcsComplt.setDisabled(false);
            btn_TeamleadrConfrm.src = '../img/bns/btn_21_d.gif';
            btn_TeamleadrConfrm.setDisabled(true);
        }
    }
};




