 * 함수명   : fn_setCheckBox
 * 설명       : 그리드 선택된 row 체크박스 선택 또는 선택해제
 ***********************************************/
scwin.fn_setCheckBox = function(grdObj, dtsObj, row) {
    //var vcd = "";
    //if (bCheck == '1')	{ vcd  = "T"; } 
    //else						{ vcd  = "F"; }

    grdObj.setBroadcast(false);
    for (var i = 1; i <= dtsObj.getTotalRow(); i++) {
        //if (i == row) {//해당row 체크
        //	dtsObj.NameString(i, "CHK") = "T";
        //} else {
        dtsObj.setCellData(i, "CHK", "F");
        //}

    }
    dtsObj.setCellData(row, "CHK", "T");
    grdObj.setBroadcast(true);
};


/**
 * 선택된 row의 값을 강제로 변경.. 이렇게 하면 변경된 row만 서버로 전송될것 같아서..
 */
scwin.fn_SetTransData = function() {
    var nRow = dts_List.getRowPosition();
    dts_List.setCellData(nRow, "CHK", "T");
};


/********************************************** 
 * 함수명   : fn_ExcelDownload
 * 설명       : 엑셀다운로드
 ***********************************************/
scwin.fn_ExcelDownload = function() {
    if (scwin.vRowCount == 0) return;
    showload.style.display = "";

    // 엑셀저장 버튼 클릭 후 바로 버튼 클릭 안되게 처리
    btn_Excel.setDisabled(true);
    btn_Excel.src = "../img/btn_excelsave_d.gif";
    var param = '';
    param += "&{P}V_MKTACT_CD=" + scwin.vMktactCd; //시장조치코드
    param += "&{P}V_BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd; //채권처리구분(1:신청,2:접수)

    //var qryId = 'lds.stf.bnspack.select.listApplBymm.excel';
    var qryId = '';
    if (scwin.vBndListProcsTpCd == '2') {
        qryId = 'lds.stf.bnscommon.select.listApplAndAcpt.excel';
    }
    var dsNm = 'BNS_APPL_ACPT_LIST_EXCEL';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List_excel, dsNm, qryId, param);
    $c.cm.ShowWin(grd_Grid_excel);
};
scwin.gform_onload = function() {
    //숨기기
    $c.stf.showObj(btn_Excel, false);
    $c.stf.showObj(lbl_ReturnPos, false);
    $c.stf.showObj(grd_Grid_excel, false);
    showload.style.display = "none";
    $c.stf.showObj(btn_StdCdReq, false);
    $c.stf.showObj(lbl_CondCapSecuTpCd, false);
    $c.stf.showObj(cmb_CondCapSecuTpCd, false);
    $c.stf.showObj(txb_EtcMemo, false);
    scwin.fn_ChgStatComp();

    //탭지정
    tab_List.setSelectedTabIndex(1);
    tab_Detail.setSelectedTabIndex(1);

    //패널라운드처리
    $c.bns.BnsPanelToGroupBox(pnl_IsuInfo);
    $c.bns.BnsPanelToGroupBox(pnl_IsurCond);
    $c.bns.BnsPanelToGroupBox(pnl_RelInst);
    $c.bns.BnsPanelToGroupBox(pnl_SplitRedmpt);
    $c.bns.BnsPanelToGroupBox(pnl_Strip);

    //시장조치구분 설정
    scwin.fn_SetMktactCd();
    scwin.fn_SetDtlTab();
    //콤보설정
    scwin.fn_SetComboCode();
    //목록조회
    scwin.fn_list_sync();

    //템프데이터셋설정

    //dts_Temp.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_Temp.insertRow();
};
scwin.dts_List_excel_OnLoadCompleted = function(rowcount) {
    showload.style.display = "none";
    $c.data.downloadGridViewExcel(grd_Grid_excel, "일괄상장 월별등록 접수목록", "", "8");

    // 엑셀저장 버튼 클릭 후 바로 버튼 클릭 안되게 처리 복구
    btn_Excel.setDisabled(false);
    btn_Excel.src = "../img/btn_excelsave.gif";
};
scwin.tab_List_OnSelChanged = function(nIndex) {
    scwin.vRowCount = 0;
    scwin.fn_ClearIsuInfo();
    scwin.vBndListProcsTpCd = nIndex;
    if (scwin.vBndListProcsTpCd == 2) {
        txb_Dtl.setValue("접수내역");
        $c.stf.showObj(btn_Excel, true);
    } else {
        scwin.vBndListProcsTpCd = '3';
        txb_Dtl.setValue("신청내역");
        $c.stf.showObj(btn_Excel, false);
    }
    scwin.fn_ChgStatComp();
    scwin.fn_list_sync();
};
scwin.dts_List_OnRowPosChanged = function(row) {
    if (row > 0) {
        scwin.vMktactCd1 = dts_List.getCellData(row, 'BND_MKTACT_TP_CD');
        scwin.fn_SetDtlTab();
        scwin.vBndApplId = dts_List.getCellData(row, "BND_APPL_ID");
        scwin.vProcsStatCd = dts_List.getCellData(row, "PROCS_STAT_CD");

        //지방채
        cmb_MunibndTpCd.setDisabled(true);
        if (scwin.vMktactCd1 == '122') {
            cmb_MunibndTpCd.setDisabled(false);
        }

        //채권유형 국채
        if (scwin.vMktactCd1 == '112') {
            $c.stf.setObjectValue(cmb_BndTpCd, 'GB');
            cmb_BndTpCd.setDisabled(true);
        }
        //지방채
        else if (scwin.vMktactCd1 == '122') {
            $c.stf.setObjectValue(cmb_BndTpCd, 'MB');
            cmb_BndTpCd.setDisabled(true);
        }
        //특수채
        else if (scwin.vMktactCd1 == '132') {
            $c.stf.setObjectValue(cmb_BndTpCd, 'AB');
            cmb_BndTpCd.setDisabled(true);
        }
        //지방공사채
        else if (scwin.vMktactCd1 == '142') {
            $c.stf.setObjectValue(cmb_BndTpCd, 'CO');
            cmb_BndTpCd.setDisabled(true);
        } else {
            cmb_BndTpCd.setDisabled(false);
        }
        scwin.fn_dtl_sync();
    }
};
