scwin.dts_IsuInfo_OnLoadCompleted = function(rowcount) {
    scwin.vRowCount = rowcount;
    //숨기기
    if (dts_List.getCellData(dts_List.getRowPosition(), 'BND_MKTACT_TP_CD') != '122') {
        $c.stf.showObj(label_47, false);
        $c.stf.showObj(cmb_MunibndTpCd, false);
    } else {
        $c.stf.showObj(label_47, true);
        $c.stf.showObj(cmb_MunibndTpCd, true);
    }

    //버튼설정
    scwin.fn_SetBtn();
    //한글금액표기
    if (rowcount > 0 && scwin.vBndListProcsTpCd == 2) {
        $c.stf.setObjectValue(txb_AmtHan, $c.bns.fn_ChgAmtToHan(dts_IsuInfo.getCellData(1, 'LIST_AMT')));
    }
    if (scwin.vBndListProcsTpCd == 2) return;
    if (rowcount > 0) {
        $c.stf.setObjectValue(edt_IsuDd, dts_List.getCellData(dts_List.getRowPosition(), "ISU_DD"));
        $c.stf.setObjectValue(edt_RedmptDd, dts_List.getCellData(dts_List.getRowPosition(), "REDMPT_DD"));
        $c.stf.setObjectValue(edt_IsuAmt, dts_List.getCellData(dts_List.getRowPosition(), "ISU_AMT"));
        $c.stf.setObjectValue(edt_ListAmt, dts_List.getCellData(dts_List.getRowPosition(), "ISU_AMT"));
        var bkbndTpCd = dts_List.getCellData(dts_List.getRowPosition(), "BKBND_TP_CD");
        //은행채
        if (bkbndTpCd == '1') {
            $c.stf.setObjectValue(edt_FstIntPayDd, dts_List.getCellData(dts_List.getRowPosition(), "FST_INT_PAY_DD"));
        }
        //은행채추가
        else if (bkbndTpCd == '3') {
            $c.stf.setObjectValue(txb_EtcMemo, '[상환기간(년) : ' + dts_List.getCellData(dts_List.getRowPosition(), "PACK_LIST_APPL_MM") + ']');
            $c.stf.setObjectValue(edt_FstIntPayDd, dts_List.getCellData(dts_List.getRowPosition(), "FST_INT_PAY_DD"));
            $c.stf.setObjectValue(edt_CoupnRt, dts_List.getCellData(dts_List.getRowPosition(), "COUPN_RT"));
            $c.stf.setObjectValue(edt_IntPayCalcMms, dts_List.getCellData(dts_List.getRowPosition(), "INT_PAY_CALC_MMS"));
            $c.stf.setObjectValue(edt_IntPayUnitMms, dts_List.getCellData(dts_List.getRowPosition(), "INT_PAY_UNIT_MMS"));
        } else {
            $c.stf.setObjectValue(txb_EtcMemo, '[발행월 : ' + dts_List.getCellData(dts_List.getRowPosition(), "PACK_LIST_APPL_MM") + ']');
        }

        //물가연동채구분
        if (dts_IsuInfo.getCellData(1, 'ISUR_CD') == 'GB035') {
            cmb_InfllnkYn.setDisabled(false);
            edt_IsuDdRefIdx.setDisabled(false);
        } else {
            cmb_InfllnkYn.setDisabled(true);
            edt_IsuDdRefIdx.setDisabled(true);
        }
    }
    $c.stf.setObjectValue(txb_AmtHan, $c.bns.fn_ChgAmtToHan(dts_IsuInfo.getCellData(1, 'LIST_AMT')));

    //금액여분적용
    scwin.fn_SetMargin();

    //신용등급 SF
    if (scwin.vBndListProcsTpCd != '1' &&
        $c.stf.getObjectValue(cmb_AsstSecutizTpCd) == '') {
        $c.stf.setObjectValue(cmb_SfValuYn1, '');
        $c.stf.setObjectValue(cmb_SfValuYn2, '');
        $c.stf.setObjectValue(cmb_SfValuYn3, '');
        $c.stf.setObjectValue(cmb_SfValuYn4, '');
        cmb_SfValuYn1.setDisabled(true);
        cmb_SfValuYn2.setDisabled(true);
        cmb_SfValuYn3.setDisabled(true);
        cmb_SfValuYn4.setDisabled(true);
    }
};
