};
scwin.btn_DelSplit_onclick = function() {
    if (dts_SplitRedmpt.getTotalRow() > 0) {
        $c.cp.removeRow(dts_SplitRedmpt, dts_SplitRedmpt.getRowPosition());
    }
};
