scwin.txb_UnqIsuEngNm_onkeyup = function() {
    var pattern = /^[ㄱ-ㅎ|ㅏ-ㅣ|가-힣]/;
    var str = $c.stf.getObjectValue(txb_UnqIsuEngNm) + ' ';
    for (var i = 0; i < str.length - 1; i++) {
        if (pattern.test(str.substring(i, i + 1))) {
            $c.win.alert('한글은 사용할 수 없습니다');
            $c.stf.setObjectValue(txb_UnqIsuEngNm, str.substring(0, str.length - 2));
        }
    }
};
scwin.cmb_AsstSecutizTpCd_OnSelChange2 = function() {
    if (scwin.vBndListProcsTpCd == '1') return;
    cmb_SfValuYn1.setDisabled(false);
    cmb_SfValuYn2.setDisabled(false);
    cmb_SfValuYn3.setDisabled(false);
    cmb_SfValuYn4.setDisabled(false);
    if ($c.stf.getObjectValue(cmb_AsstSecutizTpCd) != '') {
        if ($c.stf.getObjectValue(cmb_CreditValuInstCd1) != '') {
            $c.stf.setObjectValue(cmb_SfValuYn1, 'Y');
        }
        if ($c.stf.getObjectValue(cmb_CreditValuInstCd2) != '') {
            $c.stf.setObjectValue(cmb_SfValuYn2, 'Y');
        }
        if ($c.stf.getObjectValue(cmb_CreditValuInstCd3) != '') {
            $c.stf.setObjectValue(cmb_SfValuYn3, 'Y');
        }
        if ($c.stf.getObjectValue(cmb_CreditValuInstCd4) != '') {
            $c.stf.setObjectValue(cmb_SfValuYn4, 'Y');
        }
    } else {
        $c.stf.setObjectValue(cmb_SfValuYn1, '');
        $c.stf.setObjectValue(cmb_SfValuYn2, '');
        $c.stf.setObjectValue(cmb_SfValuYn3, '');
        $c.stf.setObjectValue(cmb_SfValuYn4, '');
        cmb_SfValuYn1.setDisabled(true);
        cmb_SfValuYn2.setDisabled(true);
        cmb_SfValuYn3.setDisabled(true);
        cmb_SfValuYn4.setDisabled(true);
    }
};
